import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    m = int(input_data[1])

    max_edges = n * (n - 1) // 2
    if m > max_edges:
        print("Impossible")
        return

    edges = []

    if n == 1:
        if m == 0:
            print("Possible")
        else:
            print("Impossible")
        return

    if m < n - 1:
        print("Impossible")
        return

    for i in range(1, n):
        if gcd(i, i + 1) == 1:
            edges.append((i, i + 1))
        else:
            print("Impossible")
            return

        if len(edges) == m:
            break

    if len(edges) < m:
        added_count = len(edges)
        for u in range(1, n + 1):
            if len(edges) >= m:
                break
            for v in range(u + 1, n + 1):
                if len(edges) >= m:
                    break
                if gcd(u, v) == 1:
                    already_added = False
                    for e in edges:
                        if (e[0] == u and e[1] == v) or (e[0] == v and e[1] == u):
                            already_added = True
                            break
                    if not already_added:
                        edges.append((u, v))

    if len(edges) < m:
        print("Impossible")
    else:
        print("Possible")
        for u, v in edges[:m]:
            print(f"{u} {v}")

if __name__ == "__main__":
    solve()
